INSERT OR IGNORE INTO datasets(id,version,title,updated_at) VALUES ('lpic-101',1,'lpic-101','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-001','lpic-101','lpic101','101 システムアーキテクチャ','101.1 ハードウェア設定','PCIデバイスを一覧表示し、ベンダーやデバイスIDを確認したい。最も適切なコマンドはどれか。','single','["lsusb","lspci","lsblk","lscpu"]',1,NULL,NULL,'lspciはPCIバス上のデバイス情報を表示する。lsusbはUSB、lsblkはブロックデバイス、lscpuはCPU情報を扱う。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","101.1"]',3,2,NULL,1,'e8025020','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-002','lpic-101','lpic101','101 システムアーキテクチャ','101.1 ハードウェア設定','カーネルが認識したCPUの詳細情報を、仮想ファイルから確認する場合に参照するものはどれか。','single','["/proc/cpuinfo","/etc/fstab","/var/log/wtmp","/boot/grub/grub.cfg"]',0,NULL,NULL,'/proc/cpuinfoにはカーネルが認識したCPU情報が公開される。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","101.1"]',3,2,NULL,1,'16461588','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-003','lpic-101','lpic101','101 システムアーキテクチャ','101.1 ハードウェア設定','USBデバイスを接続した直後に、カーネルが出力した最新メッセージを確認するコマンドはどれか。','single','["dmesg","passwd","ldd","free"]',0,NULL,NULL,'dmesgはカーネルリングバッファを表示し、デバイス認識時のメッセージ確認に使える。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","101.1"]',3,2,NULL,1,'545065f2','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-004','lpic-101','lpic101','101 システムアーキテクチャ','101.2 システムの起動','UEFI環境でブートローダーの実行ファイルが置かれる代表的な領域はどれか。','single','["EFIシステムパーティション","swap領域","/tmp専用領域","LVMのメタデータ領域"]',0,NULL,NULL,'UEFIはFAT系で作成されたEFIシステムパーティション上のEFI実行ファイルを利用する。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","101.2"]',3,2,NULL,1,'beeca2a2','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-005','lpic-101','lpic101','101 システムアーキテクチャ','101.2 システムの起動','systemdを使う環境で、今回の起動に関するログを確認するコマンドはどれか。','single','["journalctl -b","systemctl isolate","grub-install","init 0"]',0,NULL,NULL,'journalctl -bは現在のブートに対応するジャーナルを表示する。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","101.2"]',3,2,NULL,1,'09a4b686','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-006','lpic-101','lpic101','101 システムアーキテクチャ','101.2 システムの起動','Linux起動時にinitramfsが果たす役割として最も適切なものはどれか。','single','["ユーザーのホームディレクトリを暗号化する","ルートファイルシステムをマウントするまでに必要な一時的環境を提供する","すべてのユーザープロセスを終了する","パッケージリポジトリを更新する"]',1,NULL,NULL,'initramfsは必要なドライバーやツールを含む初期ルート環境として、本来のルートファイルシステムへ移行するまで利用される。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","101.2"]',3,3,NULL,1,'60ad9f7e','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-007','lpic-101','lpic101','101 システムアーキテクチャ','101.3 ランレベルとブートターゲット','systemdで次回以降の標準起動先をmulti-user.targetへ変更するコマンドはどれか。','single','["systemctl set-default multi-user.target","systemctl start multi-user.target","systemctl get-default multi-user.target","telinit multi-user.target"]',0,NULL,NULL,'set-defaultはdefault.targetの参照先を変更し、標準の起動ターゲットを設定する。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","101.3"]',3,2,NULL,1,'9e2872b8','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-008','lpic-101','lpic101','101 システムアーキテクチャ','101.3 ランレベルとブートターゲット','10分後にシステムを停止する予約を行うコマンドはどれか。','single','["shutdown -h +10","reboot --delay 10","halt -c 10","systemctl stop +10"]',0,NULL,NULL,'shutdown -h +10は10分後の停止を予約する。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","101.3"]',3,2,NULL,1,'a59346fd','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-009','lpic-101','lpic101','102 インストールとパッケージ管理','102.1 ディスクレイアウト','ログの増加でルートファイルシステム全体が圧迫されるリスクを分離したい。独立パーティション候補として最も適切なものはどれか。','single','["/var","/bin","/proc","/dev"]',0,NULL,NULL,'/varにはログや可変データが置かれるため、独立させると容量超過の影響を分離しやすい。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","102.1"]',3,2,NULL,1,'4b0b9418','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-010','lpic-101','lpic101','102 インストールとパッケージ管理','102.1 ディスクレイアウト','物理ボリューム、ボリュームグループ、論理ボリュームの順に構成する仕組みはどれか。','single','["RAID 0","LVM","NFS","GPT"]',1,NULL,NULL,'LVMはPVをVGへまとめ、その空間からLVを作成する。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","102.1"]',3,2,NULL,1,'d2300403','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-011','lpic-101','lpic101','102 インストールとパッケージ管理','102.1 ディスクレイアウト','メモリ不足時にページ退避先として利用される領域はどれか。','single','["swap","/boot","ESP","inode table"]',0,NULL,NULL,'swapはメモリページの退避などに使われる。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","102.1"]',3,2,NULL,1,'72379731','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-012','lpic-101','lpic101','102 インストールとパッケージ管理','102.2 ブートマネージャ','GRUB 2の設定生成に使われ、多くの環境で直接手編集を避けるべきファイルはどれか。','single','["/boot/grub/grub.cfg","/etc/passwd","/etc/hosts","/var/lib/dpkg/status"]',0,NULL,NULL,'grub.cfgは生成物であり、通常は/etc/default/grubや/etc/grub.d配下を変更して再生成する。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","102.2"]',3,3,NULL,1,'b1242598','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-013','lpic-101','lpic101','102 インストールとパッケージ管理','102.2 ブートマネージャ','GRUB 2で設定ファイルを生成する代表的なコマンドはどれか。','single','["grub-mkconfig","grub-shell-save","bootctl mount","mkfs.grub"]',0,NULL,NULL,'grub-mkconfigはスクリプトと既定値からGRUB 2設定を生成する。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","102.2"]',3,2,NULL,1,'029e60f3','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-014','lpic-101','lpic101','102 インストールとパッケージ管理','102.2 ブートマネージャ','起動時にカーネルへ一時的な引数を追加して検証したい。最も適切な操作はどれか。','single','["GRUBメニューで対象エントリを編集してlinux行へ追記する","/etc/fstabを削除する","swapを初期化する","BIOS時刻を変更する"]',0,NULL,NULL,'GRUBメニューで一時編集すれば、永続設定を変えずにその起動だけカーネル引数を試せる。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","102.2"]',3,2,NULL,1,'b783e1d9','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-015','lpic-101','lpic101','102 インストールとパッケージ管理','102.3 共有ライブラリ','実行ファイルが必要とする共有ライブラリを確認するコマンドはどれか。','single','["ldd","ldconfig -pのみ","filefrag","depmod"]',0,NULL,NULL,'lddは対象実行ファイルの共有ライブラリ依存関係と解決先を表示する。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","102.3"]',3,2,NULL,1,'2ce299f2','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-016','lpic-101','lpic101','102 インストールとパッケージ管理','102.4 Debianパッケージ管理','ローカルにあるsample.debをdpkgでインストールするコマンドはどれか。','single','["dpkg -i sample.deb","dpkg -S sample.deb","apt-cache sample.deb","rpm -i sample.deb"]',0,NULL,NULL,'dpkg -iは指定したdebパッケージをインストールする。依存関係解決はapt系コマンドで補う場合がある。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","102.4"]',3,2,NULL,1,'331ee448','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-017','lpic-101','lpic101','102 インストールとパッケージ管理','102.4 Debianパッケージ管理','Debian系で、あるファイルがどのインストール済みパッケージに属するか調べるコマンドはどれか。','single','["dpkg -S /path/to/file","dpkg -L /path/to/file","apt remove /path/to/file","ldd /path/to/file"]',0,NULL,NULL,'dpkg -Sはファイル名から所有パッケージを検索する。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","102.4"]',3,2,NULL,1,'3022c9cb','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-018','lpic-101','lpic101','102 インストールとパッケージ管理','102.4 Debianパッケージ管理','APTでリポジトリのパッケージ索引を更新する操作はどれか。','single','["apt update","apt upgrade","apt clean","apt show"]',0,NULL,NULL,'apt updateはパッケージ索引を取得・更新する。upgradeは更新可能なパッケージの導入を行う。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","102.4"]',3,2,NULL,1,'7ebd24b2','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-019','lpic-101','lpic101','102 インストールとパッケージ管理','102.5 RPM・YUM・DNF','RPMデータベースに対し、あるファイルの所有パッケージを問い合わせるコマンドはどれか。','single','["rpm -qf /path/to/file","rpm -ql /path/to/file","rpm -ivh /path/to/file","dnf clean /path/to/file"]',0,NULL,NULL,'rpm -qfは指定ファイルを所有するインストール済みパッケージを表示する。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","102.5"]',3,2,NULL,1,'dc240fa4','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-020','lpic-101','lpic101','102 インストールとパッケージ管理','102.5 RPM・YUM・DNF','RPM系で依存関係を解決しながらパッケージを導入する高レベルツールはどれか。','single','["dnf","ldconfig","dpkg-deb","make"]',0,NULL,NULL,'DNFやYUMはリポジトリ情報を使って依存関係を解決する。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","102.5"]',3,2,NULL,1,'239523c0','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-021','lpic-101','lpic101','102 インストールとパッケージ管理','102.5 RPM・YUM・DNF','インストール済みRPMパッケージが提供するファイル一覧を表示するコマンドはどれか。','single','["rpm -ql package","rpm -qf package","rpm -e --test package","yum repolist package"]',0,NULL,NULL,'rpm -qlはパッケージに含まれるファイルの一覧を問い合わせる。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","102.5"]',3,2,NULL,1,'63ad64b0','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
