INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-031','lpic-101','lpic101','103 GNUとUNIXコマンド','103.3 ファイル管理','カレントディレクトリ以下から、7日より前に更新された通常ファイルを検索する条件はどれか。','single','["find . -type f -mtime +7","find . -type d -mtime -7","locate . -mtime +7","which . -type f"]',0,NULL,NULL,'findの-type fで通常ファイル、-mtime +7で指定日数より前の更新を条件にする。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","103.3"]',3,2,NULL,1,'0b3dc3b1','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
