INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-033','lpic-101','lpic101','103 GNUとUNIXコマンド','103.4 ストリームとリダイレクト','標準出力と標準エラー出力を同じlog.txtへ上書き保存するBashの記述はどれか。','single','["command >log.txt 2>&1","command <log.txt 2>&1","command 2>1 >log.txt","command |< log.txt"]',0,NULL,NULL,'まず標準出力をlog.txtへ向け、2>&1で標準エラーを現在の標準出力と同じ宛先へ向ける。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","103.4"]',3,3,NULL,1,'a6376b50','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
