INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-035','lpic-101','lpic101','103 GNUとUNIXコマンド','103.4 ストリームとリダイレクト','dateコマンドの出力を変数todayへ代入するBashの記述はどれか。','single','["today=$(date)","today=${date}","today=|date","date > $today"]',0,NULL,NULL,'$(...)はコマンド置換であり、標準出力を文字列として利用できる。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","103.4"]',3,2,NULL,1,'976ba724','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
