INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-037','lpic-101','lpic101','103 GNUとUNIXコマンド','103.5 プロセス管理','PID 4242へ通常の終了要求を送るコマンドはどれか。','single','["kill -TERM 4242","kill -KILL -1","jobs 4242","bg 4242"]',0,NULL,NULL,'SIGTERMはプロセスに後処理の機会を与える通常の終了要求で、既定シグナルでもある。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","103.5"]',3,2,NULL,1,'dce97703','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-038','lpic-101','lpic101','103 GNUとUNIXコマンド','103.5 プロセス管理','SSH接続が切れても長時間作業の端末状態を維持し、後から再接続したい。適したツールはどれか。','single','["tmux","nice","xargs","sed"]',0,NULL,NULL,'tmuxやGNU Screenは端末セッションを分離・再接続できる。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","103.5"]',3,2,NULL,1,'89ba34d4','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-039','lpic-101','lpic101','103 GNUとUNIXコマンド','103.6 プロセス優先度','Linuxのnice値について正しい説明はどれか。','single','["値が大きいほど一般にCPU優先度は低くなる","値が大きいほど必ずリアルタイム実行になる","一般ユーザーは任意に負の値へ変更できる","nice値はディスク容量を表す"]',0,NULL,NULL,'通常スケジューリングではnice値が大きいほど譲歩的になり、優先度は低くなる。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","103.6"]',3,2,NULL,1,'5c381956','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-040','lpic-101','lpic101','103 GNUとUNIXコマンド','103.6 プロセス優先度','既に動作中のPID 5000のnice値を10へ変更するコマンドはどれか。','single','["renice 10 -p 5000","nice 10 -p 5000","priority 10 5000","ps --nice 10 5000"]',0,NULL,NULL,'reniceは実行中プロセスのnice値を変更する。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","103.6"]',3,2,NULL,1,'bbade9c1','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-041','lpic-101','lpic101','103 GNUとUNIXコマンド','103.7 正規表現','grepの基本正規表現で、行頭がrootの行を検索するパターンはどれか。','single','["^root","root$",".root","[root]$"]',0,NULL,NULL,'^は行頭を表すアンカーである。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","103.7"]',3,2,NULL,1,'62ad522c','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-042','lpic-101','lpic101','103 GNUとUNIXコマンド','103.7 正規表現','拡張正規表現でcatまたはdogのどちらかに一致させるパターンをgrepで使う例はどれか。','single','["grep -E ''cat|dog''","grep -F ''cat|dog''","grep -v ''cat&dog''","grep -n ''cat,dog''"]',0,NULL,NULL,'拡張正規表現では|が選択を表し、grep -Eで利用できる。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","103.7"]',3,2,NULL,1,'2df38a19','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-043','lpic-101','lpic101','103 GNUとUNIXコマンド','103.7 正規表現','sedで各行の最初に現れるoldをnewへ置換する式はどれか。','single','["sed ''s/old/new/''","sed ''d/old/new/''","sed ''p/old/new/''","sed ''y/old/new/g''"]',0,NULL,NULL,'sコマンドは置換を行う。gフラグがなければ各行の最初の一致を置換する。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","103.7"]',3,2,NULL,1,'7bff93d9','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
