INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-045','lpic-101','lpic101','104 デバイスとファイルシステム','104.1 パーティションとファイルシステム','新しいext4ファイルシステムを/dev/sdb1へ作成するコマンドはどれか。','single','["mkfs.ext4 /dev/sdb1","fsck.ext4 /dev/sdb1","mount.ext4 /dev/sdb1","tune2fs -l /dev/sdb1"]',0,NULL,NULL,'mkfs.ext4は対象ブロックデバイスへext4ファイルシステムを作成する。実行すると既存データを失うため対象確認が重要である。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","104.1"]',3,2,NULL,1,'ac9e2016','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-046','lpic-101','lpic101','104 デバイスとファイルシステム','104.2 ファイルシステム整合性','アンマウント済みext系ファイルシステムの整合性を検査・修復する代表的なコマンドはどれか。','single','["fsck","mkfifo","mount","quotaon"]',0,NULL,NULL,'fsckはファイルシステム検査のフロントエンドである。原則として対象をアンマウントして実行する。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","104.2"]',3,2,NULL,1,'1b186dcb','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-047','lpic-101','lpic101','104 デバイスとファイルシステム','104.3 マウントとアンマウント','/etc/fstabでUUIDを使う主な利点はどれか。','single','["デバイス名の列挙順が変わっても対象を安定して識別しやすい","ファイルシステムを自動的に暗号化する","容量を無制限にできる","root権限が不要になる"]',0,NULL,NULL,'UUIDはファイルシステム固有の識別子で、/dev/sdXのような列挙順依存の名前より安定する。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","104.3"]',3,2,NULL,1,'060de0bd','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-048','lpic-101','lpic101','104 デバイスとファイルシステム','104.5 パーミッションと所有権','ディレクトリへsetgidビットを設定した場合の代表的な効果はどれか。','single','["新規作成物がディレクトリのグループを継承しやすくなる","誰でも削除できなくなる","所有者がrootへ固定される","実行ファイルが必ずroot権限で動く"]',0,NULL,NULL,'ディレクトリのsetgidは配下に作成されるファイルやディレクトリのグループ継承に利用される。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","104.5"]',3,3,NULL,1,'520a125c','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
INSERT OR IGNORE INTO questions (id,dataset_id,exam_scope_id,category,subcategory,text,question_type,choices_json,answer_index,answer_indices_json,accepted_answers_json,explanation,source,tags_json,weight,difficulty,archived_at,revision,content_hash,created_at,updated_at) VALUES ('LPIC101-049','lpic-101','lpic101','104 デバイスとファイルシステム','104.6 ハードリンクとシンボリックリンク','ハードリンクについて正しい説明はどれか。','single','["元のパス名が削除されても、同じinodeへの別リンクが残ればデータへアクセスできる","必ず別ファイルシステムを越えて作成できる","ディレクトリへ常に自由に作成できる","リンク先パス文字列だけを保持する"]',0,NULL,NULL,'ハードリンクは同じinodeを参照する別ディレクトリエントリである。通常はファイルシステムを越えられない。','LPI Learning Materials LPIC-1 Exam 101 (101-500) Version 5.0 日本語版の学習範囲を参考にしたオリジナル問題 https://learning.lpi.org/ja/learning-materials/101-500/','["LPIC-1","101","104.6"]',3,2,NULL,1,'7d5d1884','2026-10-11T00:00:00.000Z','2026-10-11T00:00:00.000Z');
